        for (int i = 0; i < LEFT_TO_RIGHT.length; i += 2) {
            String old = LEFT_TO_RIGHT[i];
            String n = LEFT_TO_RIGHT[i+1];
            if (name.endsWith(old)) {
                return name.substring(0, name.length() - old.length()) + n;
            }
        }
        return name;
    }

    public static String convertNewToOld(String name) {
        for (int i = 0; i < LEFT_TO_RIGHT.length; i += 2) {
