            Attr attr = (Attr) node;
            if (ANDROID_URI.equals(attr.getNamespaceURI())) {
                String name = attr.getLocalName();
                if (name == null || name.isEmpty()) {
                    name = attr.getName();
                    int colon = name.indexOf(':');
                    if (colon != -1) {
                        name = name.substring(colon + 1);
                    }
                }
                names.add(name);
                attrs.put(name, attr);
            }
        }
    }

    boolean checkRtlCompat = context.getMainProject().getMinSdkVersion() < 17;
    if (checkRtlCompat) {
        for (String name : names) {
            if (isRtlAttributeName(name)) {
                String old = convertNewToOld(name);
                if (old != null && !old.equals(name) && !names.contains(old)) {
